212	// Records flagged true and false survive a close/reopen of the same database
213	// file with every field and the global order intact. Re-posting the original
214	// policy afterwards returns 200 with the stored record — the old conflict flag
215	// is not recomputed even though an opposite-action policy now exists — and a
216	// pluginParams object with reordered members still counts as the same content.
217	func TestConflictFlagsSurviveStoreReopen(t *testing.T) {
218		dbPath := filepath.Join(t.TempDir(), "service.db")
219		st, err := store.Open(dbPath)
220		if err != nil {
221			t.Fatalf("open: %v", err)
222		}
223		router := NewRouter(st)
224	
225		seedBody := singleRuleBody("payments", "deny-web", "tier=backend", "ingress", "deny", 80, 100,
226			`{"mode": "enforce", "zone": "east"}`)
