798		// Different final content is still a conflict rather than an overwrite.
799		conflict := doRequest(router, http.MethodPost, "/v1/net-policies",
800			policyBody("payments", "default-deny", "tier=backend",
801				`{"mode": "audit", "mode": "audit"}`))
802		if conflict.Code != http.StatusConflict {
803			t.Fatalf("changed retry status = %d, want %d: %s", conflict.Code, http.StatusConflict, conflict.Body.String())
804		}
805		assertErrorCode(t, conflict, "NetPolicyConflictError")
806	
807		next := doRequest(router, http.MethodPost, "/v1/net-policies",
808			policyBody("payments", "after", "tier=backend",
809				`{"mode": "x", "mode": "x"}`))
810		if next.Code != http.StatusCreated {
811			t.Fatalf("next status = %d, want %d: %s", next.Code, http.StatusCreated, next.Body.String())
812		}
813		json.Unmarshal(next.Body.Bytes(), &body)
814		if body["order"] != float64(2) {
815			t.Fatalf("next order = %v, want 2", body["order"])
816		}
817		if !reflect.DeepEqual(body["pluginParams"], map[string]any{"mode": "x"}) {
818			t.Fatalf("next pluginParams = %v, want single final key", body["pluginParams"])
819		}
820	
821		items := listItems(t, router, "/v1/net-policies?namespace=payments")
822		if len(items) != 2 {
823			t.Fatalf("items = %v, want 2 records", items)
824		}
825	}
826	
827	func assertErrorCode(t *testing.T, recorder *httptest.ResponseRecorder, want string) {
828		t.Helper()
829		var body map[string]map[string]string
830		if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
831			t.Fatalf("decode error body: %v", err)
832		}
